import{_ as d,o as r,c as a,a2 as e}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"शब्दावली-कोश","description":"","frontmatter":{},"headers":[],"relativePath":"hi/90-术语词典.md","filePath":"hi/90-术语词典.md","lastUpdated":1789183869000}'),i={name:"hi/90-术语词典.md"};function l(h,t,o,n,s,_){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="शब्दावली-कोश" tabindex="-1">शब्दावली-कोश <a class="header-anchor" href="#शब्दावली-कोश" aria-label="Permalink to &quot;शब्दावली-कोश&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>90</td></tr><tr><td>मॉड्यूल</td><td>परिशिष्ट और संदर्भ-सामग्री</td></tr><tr><td>कीवर्ड</td><td>शब्दावली-कोश, मूल अवधारणाएँ, परिभाषाएँ, एकीकृत शब्दावली, हेंग-ब्रह्मांड</td></tr></tbody></table><h2 id="i-शब्दावली-संबंधी-टिप्पणियाँ" tabindex="-1">I. शब्दावली-संबंधी टिप्पणियाँ <a class="header-anchor" href="#i-शब्दावली-संबंधी-टिप्पणियाँ" aria-label="Permalink to &quot;I. शब्दावली-संबंधी टिप्पणियाँ&quot;">​</a></h2><p>यह कोश लंगर सहजीवी सभ्यता की विश्व-रचना प्रणाली के मूल शब्दों को संग्रहीत करता है, जिसका उद्देश्य सभी दस्तावेज़ों में शब्द-प्रयोग को एकीकृत करना और अवधारणा-अभिव्यक्ति की संगति तथा शुद्धता सुनिश्चित करना है। सभी शब्द उनके चीनी पिनयिन के प्रथम अक्षर के अनुसार क्रमबद्ध हैं; प्रत्येक प्रविष्टि में शब्द-नाम, अंग्रेज़ी संदर्भ-नाम (यदि हो), परिभाषा और संक्षिप्त व्याख्या शामिल है। यह कोश एक गतिशील-अद्यतन दस्तावेज़ है; विश्व-रचना प्रणाली के विस्तार के साथ नए शब्द निरंतर जोड़े जाते रहेंगे।</p><h2 id="ii-मूल-शब्द-तालिका" tabindex="-1">II. मूल शब्द-तालिका <a class="header-anchor" href="#ii-मूल-शब्द-तालिका" aria-label="Permalink to &quot;II. मूल शब्द-तालिका&quot;">​</a></h2><table tabindex="0"><thead><tr><th>क्र.</th><th>शब्द</th><th>परिभाषा और व्याख्या</th></tr></thead><tbody><tr><td>1</td><td>लंगर</td><td>नियम-नेटवर्क में स्थिर नोड, जो पटल-नियमों की स्थिरता बनाए रखने, अंतर-पटल संबंध और समय-प्रत्यावर्तन के लिए समन्वय-आधार का कार्य करता है। मूल रूप से लंगर किसी विशिष्ट स्थानिक-स्थान पर ब्रह्मांड के मूल-नियमों का उच्च-घनत्व संघनन है, जिसमें स्व-रखरखाव और अंशांकन क्षमता होती है।</td></tr><tr><td>2</td><td>लंगर सहजीवी सभ्यता</td><td>लंगर-तंत्र को तकनीकी-आधार और सहजीवी विकास को मूल-अवधारणा बनाने वाली सभ्यता-रूप। यह शिकारी-कृषि प्रणाली का विरोध करती है और भाग्य तथा विकास के चयन-अधिकार सभी जीवों को लौटाने की वकालत करती है, जिससे अधिक श्रम-अधिक लाभ, स्व-वृद्धि, हर किसी के लिए मार्ग, और दस हज़ार जातियों की साझा प्रगति हो।</td></tr><tr><td>3</td><td>हेंग-ब्रह्मांड</td><td>«वानलिंग हेंगमाओ मूल-ब्रह्मांड» का संक्षिप्त रूप, वह सम्पूर्ण ब्रह्मांडीय क्षेत्र जहाँ लंगर सहजीवी सभ्यता निवास और शासन करती है। यह चार स्तरों से निर्मित संयुक्त अस्तित्व है: भौतिक-पटल, ऊर्जा-स्तर, चेतना-क्षेत्र और नियम-नेटवर्क।</td></tr><tr><td>4</td><td>वानलिंग हेंगमाओ मूल-ब्रह्मांड</td><td>हेंग-ब्रह्मांड का पूर्ण नाम। «वानलिंग» (दस हज़ार आत्माएँ) उन सभी जीवन-रूपों को सूचित करता है जिनमें अनुभूति और विकास-क्षमता है; «हेंगमाओ» (संतुलन-लंगर) ब्रह्मांडीय संतुलन बनाए रखने वाले लंगर-तंत्र को सूचित करता है; «मूल-ब्रह्मांड» मूल-नियमों को आधार और सहजीवी विकास को दिशा बनाने के मूल गुणों पर बल देता है।</td></tr><tr><td>5</td><td>सहजीवन</td><td>लंगर सहजीवी सभ्यता की मूल अवधारणाओं में से एक, जो विभिन्न जीव-व्यक्तियों, जातियों और सभ्यताओं के परस्पर-लाभकारी सहयोग से साझा विकास को सूचित करता है, न कि दूसरों की कीमत पर शिकारी विकास को।</td></tr><tr><td>6</td><td>शिकारी-कृषि प्रणाली</td><td>दुर्बलों की ऊर्जा, भाग्य और यहाँ तक कि मूल-स्रोत को निगलकर स्व-विकास प्राप्त करने की कृषि-विधि। यह वह प्रणाली-प्रकार है जिसका लंगर सहजीवी सभ्यता दृढ़तापूर्वक विरोध करती है, और जिसे ब्रह्मांडीय एन्ट्रापी-वृद्धि में तीव्रता और सभ्यता-विच्छेदों की बारंबारता का मूल-कारण माना जाता है।</td></tr><tr><td>7</td><td>तीन सौ मूल-कृषि प्रणालियाँ</td><td>ब्रह्मांड के मूल-नियमों से सीधे निष्कर्षित और लंगरों द्वारा सत्यापित परम्परागत कृषि-पथ, कुल तीन सौ, छह प्रमुख वर्गों में विभाजित: मूल-निष्कर्षण, जीवन-चक्र, स्थान-न्यायिक, चेतना-उन्नयन, सहजीवी-नेटवर्क और अनुप्रयोग-इंजीनियरिंग, प्रत्येक वर्ग में पचास प्रणालियाँ।</td></tr><tr><td>8</td><td>मूल-त्रय आधार</td><td>तीन सौ प्रणालियों में पहली तीन मूलभूत प्रणालियाँ — निष्कर्षण-पुनरावृत्ति प्रणाली (पहली), जीवन-चक्र प्रणाली (दूसरी) और स्थान-न्यायिक सिद्धांत-प्रेषण प्रणाली (तीसरी) — जो अन्य सभी प्रणालियों की कृषि-नींव हैं।</td></tr><tr><td>9</td><td>निष्कर्षण-पुनरावृत्ति प्रणाली</td><td>प्रथम मूल-कृषि प्रणाली, जिसकी विशेषता सौ गुना कृषि-निष्कर्षण वृद्धि है, जो गुणक-फल के तकनीकी अनुप्रयोग से निष्कर्षण-क्षमता को सौ गुना बढ़ाती है, और निष्कर्षण, सत्यापन और पुनरावृत्ति द्वारा कृषि-पथ अनुकूलन पर बल देती है।</td></tr><tr><td>10</td><td>जीवन-चक्र प्रणाली</td><td>द्वितीय मूल-कृषि प्रणाली, जो जीवन-ऊर्जा के सद्गुणी चक्र को केंद्र बनाती है, और इस बात पर बल देती है कि कृषक और पर्यावरण के बीच ऊर्जा-विनिमय चक्रीय होना चाहिए, शिकारी नहीं।</td></tr><tr><td>11</td><td>स्थान-न्यायिक सिद्धांत-प्रेषण प्रणाली</td><td>तृतीय मूल-कृषि प्रणाली, जो स्थान-नियमों की समझ और प्रेषण को केंद्र बनाती है, अंतर-पटल अंतःक्रिया, पृथक-स्थान निर्माण और प्रतिकृति-दर्पण प्रौद्योगिकी जैसे महत्वपूर्ण अनुप्रयोगों की कृषि-नींव है।</td></tr><tr><td>12</td><td>गुणक-फल</td><td>वन पीस-लोक से उत्पन्न गुणक-फल, जो हेंग-ब्रह्मांड में तकनीकी रूप से अनुप्रयुक्त है, कृषक की निष्कर्षण-क्षमता को सौ गुना बढ़ा सकता है, और निष्कर्षण-पुनरावृत्ति प्रणाली का केंद्रीय सहायक उपकरण है। प्रारंभिक-बफ़ों में से एक।</td></tr><tr><td>13</td><td>उत्पादन-आधारित अनुबंध तंत्र</td><td>लंगर सहजीवी सभ्यता का संसाधन-वितरण तंत्र, जो ब्रह्मांडीय कृषि-संसाधनों को «अनुबंध» के रूप में व्यक्तियों या समूहों को आवंटित करता है; अनुबंधकर्ता श्रम और योगदान से संसाधन-उपयोग-अधिकार प्राप्त करते हैं, जिससे अधिक श्रम-अधिक लाभ सिद्ध होता है।</td></tr><tr><td>14</td><td>20% सक्रियण-रणनीति</td><td>लंगर सहजीवी सभ्यता का चरणबद्ध रणनीतिक लक्ष्य: प्रारंभिक चरण में ब्रह्मांड के 20% जीवों को पटल-परम शक्ति बनाना, उन्हें कंकाल बनाकर शेष 80% जीवों के साझा विकास को आगे बढ़ाना।</td></tr><tr><td>15</td><td>पटल-परम शक्ति</td><td>वह शक्तिशाली जो अत्यंत उच्च स्तर तक कृषि कर चुका हो और किसी पटल की नियम-स्थिरता को स्वतंत्र रूप से बनाए रख सके। यह 20% सक्रियण-रणनीति का लक्ष्य-प्रशिक्षण-विषय और लंगर-नेटवर्क की महत्वपूर्ण रखरखाव-शक्ति है।</td></tr><tr><td>16</td><td>नियम-नेटवर्क</td><td>हेंग-ब्रह्मांड संरचना का चतुर्थ स्तर, ब्रह्मांड के मूल-नियमों का संचालन-आधार और लंगरों का मूल-आधार। नियम-नेटवर्क सम्पूर्ण ब्रह्मांड में व्याप्त है, और सभी नियम-संचालनों (स्थान-प्रेषण, समय-प्रत्यावर्तन, ऊर्जा-रूपांतरण सहित) का तकनीकी आधार है।</td></tr><tr><td>17</td><td>पटल</td><td>अपेक्षाकृत स्थिर नियम-समूह द्वारा परिभाषित, स्वतंत्र स्थान-काल-सातत्य वाला अस्तित्व-क्षेत्र। प्रत्येक पटल के अद्वितीय भौतिक-स्थिरांक, ऊर्जा-घनत्व, समय-प्रवाह-गति और चेतना-सक्रियता-स्तर होते हैं।</td></tr><tr><td>18</td><td>नियम-अवरोध</td><td>निकटवर्ती पटलों को विभाजित करने वाला नियम-परिरोध, जिसकी मजबूती निकटवर्ती पटलों के नियम-प्राचलों में अंतर की मात्रा पर निर्भर करती है। पटल-संचरण के लिए नियम-अवरोधों को पार करना आवश्यक है।</td></tr><tr><td>19</td><td>नियम-अंगुलिछाप</td><td>प्रत्येक पटल के मूल नियम-प्राचलों पर हैश-संचालन से उत्पन्न अद्वितीय पहचान-चिह्न, जिसकी लंबाई 128 बिट होती है, जो पटल-समन्वय प्रणाली के मूल प्राचलों में से एक है।</td></tr><tr><td>20</td><td>पहले अवलोकन, फिर सीमित हस्तक्षेप</td><td>समय-प्रत्यावर्तन और अंतर-पटल पुरातत्व का प्रथम संचालन-सिद्धांत, जो माँग करता है कि कोई भी प्रत्यावर्तन या पुरातत्व पहले शुद्ध-अवलोकन चरण पूर्ण करे, और बड़े जोखिमों की अनुपस्थिति की पुष्टि के बाद ही सीमित हस्तक्षेप करे।</td></tr><tr><td>21</td><td>प्रतिकृति-दर्पण</td><td>स्थान-न्यायिक नियमों पर आधारित उच्च-परिशुद्ध प्रतिकृति-उपकरण, जो मूल वस्तु को स्पर्श किए बिना लक्ष्य-क्षेत्र की 1:1 पूर्ण प्रतिकृति बना सकता है, बाह्य-स्थल पुरातत्व-योजना का केंद्रीय उपकरण है।</td></tr><tr><td>22</td><td>पृथक-स्थान</td><td>स्थान-न्यायिक सिद्धांत-प्रेषण प्रौद्योगिकी से निर्मित स्वतंत्र नियम-क्षेत्र, जो पुरातत्व-प्रति को धारण करने और पुरातत्व-कर्मियों के कार्य-स्थान के रूप में उपयोग होता है, और बाह्य ब्रह्मांड से नियम-अवरोधों द्वारा पूर्णतः पृथक होता है।</td></tr><tr><td>23</td><td>केवल-ज्ञान-वापसी</td><td>पुरातत्व-प्रोटोकॉल का मूल सिद्धांत, जिसका अर्थ है कि पुरातत्व-प्रक्रिया में लक्ष्य-वस्तु से केवल अमूर्त ज्ञान और सूचना प्राप्त की जा सकती है; कोई पदार्थ, ऊर्जा या जीव वापस नहीं भेजा जा सकता।</td></tr><tr><td>24</td><td>सूचना-शुद्धिकरण</td><td>कच्ची सूचना में निहित स्रोत-पटल की नियम-छापों को पूर्णतः हटाकर केवल शुद्ध अर्थ-सामग्री बनाए रखने की तकनीकी प्रक्रिया, जो वापस भेजे गए ज्ञान की सुरक्षा सुनिश्चित करने की कुंजी-कड़ी है।</td></tr><tr><td>25</td><td>समय-विरोधाभास</td><td>समय-प्रत्यावर्तन संचालनों में हस्तक्षेप-व्यवहार के कारण कारण-तर्क के स्वविरोधाभासी होने की घटना, जिसमें पितृ-हत्या विरोधाभास, सूचना-विरोधाभास, तत्त्व-विरोधाभास और घटना-विरोधाभास चार प्रमुख वर्ग शामिल हैं।</td></tr><tr><td>26</td><td>कारण-श्रृंखला</td><td>घटनाओं के बीच कारण-कार्य की सतत रैखिक संरचना, समय-नियमों की मूल अवधारणा। समय-प्रत्यावर्तन संचालनों का मूल जोखिम कारण-श्रृंखला का व्यवधान है।</td></tr><tr><td>27</td><td>सहजीवी संविधान</td><td>लंगर सहजीवी सभ्यता का मूल विधान, जिसकी सर्वोच्च कानूनी शक्ति है, जो शिकार-विरोध और सहजीवन-समर्थन की सभ्यता-नींव तथा सात मूल संवैधानिक सिद्धांतों को स्थापित करता है।</td></tr><tr><td>28</td><td>दस हज़ार जातियों की समानता</td><td>सहजीवी संविधान के सात मूल सिद्धांतों में से एक, जिसका अर्थ है कि सभी जीवन-रूप, चाहे जाति, कृषि-स्तर या उत्पत्ति कुछ भी हो, कानून के समक्ष समान हैं।</td></tr><tr><td>29</td><td>विचित्र जीवन</td><td>ऐसे जीवन-रूप जो परम्परागत जीवन-परिभाषा के अनुरूप नहीं हैं और जिनमें विशेष अस्तित्व-रूप हैं, जिनकी पहचान और प्रबंधन तीन-वर्गीय मानकीकृत निपटान-प्रक्रियाओं के अनुसार आवश्यक है।</td></tr><tr><td>30</td><td>विचित्र ऊर्जा</td><td>ऐसे ऊर्जा-रूप जो परम्परागत ऊर्जा-वर्गीकरण के अनुरूप नहीं हैं और जिनमें विशेष गुण और व्यवहार-प्रतिमान हैं, जिनका वर्गीकरण और नियंत्रण तीन-वर्गीय मानकीकृत निपटान-प्रक्रियाओं के अनुसार आवश्यक है।</td></tr><tr><td>31</td><td>अंधकार प्रतिस्थापन इकाई</td><td>एक विशेष जीवन-रूप जो द्वि-आत्मा सहअस्तित्व की नैतिक समस्या से संबंधित है, जिसका प्रबंधन द्वि-आत्मा नैतिकता सिद्धांत और चार-वर्गीय शाखा-निपटान नियमों के अनुसार आवश्यक है।</td></tr><tr><td>32</td><td>द्वि-आत्मा नैतिकता</td><td>अंधकार प्रतिस्थापन इकाई में दो आत्माओं के सहअस्तित्व-रूप के लिए नैतिक सिद्धांत, जिसका केंद्र दोनों आत्माओं के क्रमशः अधिकारों का सम्मान और किसी एक पक्ष का जबरन सम्मिलन या विनाश निषिद्ध करना है।</td></tr><tr><td>33</td><td>पाँच सहजीवी सभ्यता-प्रकार</td><td>वास्तविक-विश्व की सभ्यता-विशेषताओं के आधार पर विभाजित पाँच सहजीवी समाज-प्रकार: पूर्वी-एशियाई गहन प्रकार, नॉर्डिक कल्याण प्रकार, उत्तर-अमेरिकी बहुलवादी प्रकार, यूरोपीय-मुख्यभूमि सामाजिक प्रकार, और विकासशील-पीछा-कर-पकड़ प्रकार।</td></tr><tr><td>34</td><td>चार-चरणीय उन्नयन-पथ</td><td>हेंग-ब्रह्मांड के समग्र उन्नयन की चार-चरणीय रूपरेखा: वास्तविक-आधार → प्रौद्योगिकी-सशक्तिकरण → चेतना-विकास → अंतरतारकीय सहजीवन।</td></tr><tr><td>35</td><td>वास्तविकता-आधार</td><td>लंगर सहजीवी सभ्यता की मूल स्थितियों में से एक, जिसका अर्थ है कि वास्तविक विश्व ही एकमात्र वास्तविक विश्व है, उपन्यास-लोक झूठे विचार-प्रयोग हैं, कल्पना में कमी वास्तविकता से पूरी की जाती है, और वास्तविकता में जो नहीं है वह नियमों के आधार पर उन्नयन-सृजन से बनाया जाता है।</td></tr><tr><td>36</td><td>सहजीवन-सूचकांक</td><td>किसी सभ्यता या व्यक्ति के सहजीवी-नेटवर्क के साथ सम्मिलन-मात्रा का आकलन करने वाला मात्रात्मक संकेतक, जिसमें संसाधन-साझेदारी-मात्रा, सहयोग-आवृत्ति, परोपकारी-व्यवहार-अनुपात जैसे कई आयाम शामिल हैं।</td></tr><tr><td>37</td><td>लंगर विधान-सभा</td><td>लंगर सहजीवी सभ्यता का सर्वोच्च अधिकार-संस्था, जो दस हज़ार जातियों के प्रतिनिधियों से अनुपातानुसार गठित होती है, और विधायी-अधिकार तथा महत्वपूर्ण मामलों के निर्णय-अधिकार का प्रयोग करती है।</td></tr><tr><td>38</td><td>सहजीवी कार्यकारी समिति</td><td>लंगर सहजीवी सभ्यता की सर्वोच्च प्रशासनिक संस्था, जो संविधान और कानूनों के निष्पादन तथा दैनिक शासन के लिए उत्तरदायी है।</td></tr><tr><td>39</td><td>सहजीवी न्यायालय</td><td>लंगर सहजीवी सभ्यता का सर्वोच्च न्यायिक संस्थान, जो स्वतंत्र रूप से न्याय-अधिकार का प्रयोग करता है, और संविधान-जाँच तथा महत्वपूर्ण मामलों के विचारण के लिए उत्तरदायी है।</td></tr><tr><td>40</td><td>पटल प्रशासन</td><td>लंगर विधान-सभा के अधीनस्थ विशेष संस्था, जो पटल-समन्वय मूल-भंडार के रखरखाव, संचरण-अनुमति अनुमोदन और अंतर-पटल पुरातत्व प्रबंधन जैसे कार्यों के लिए उत्तरदायी है।</td></tr></tbody></table><h2 id="iii-शब्दावली-उपयोग-मानक" tabindex="-1">III. शब्दावली-उपयोग मानक <a class="header-anchor" href="#iii-शब्दावली-उपयोग-मानक" aria-label="Permalink to &quot;III. शब्दावली-उपयोग मानक&quot;">​</a></h2><ol><li>इस कोश में संग्रहीत शब्द मानक शब्द हैं; सभी दस्तावेज़ों को इस कोश के मानक अभिव्यक्तियों को प्राथमिकता देनी चाहिए।</li><li>एक ही अवधारणा के लिए विभिन्न दस्तावेज़ों में वही शब्द उपयोग होना चाहिए; मनमाने ढंग से पर्यायवाची नहीं बदले जाने चाहिए।</li><li>नई विश्व-रचना में उत्पन्न नए शब्द समय पर शब्दावली-समिति के समक्ष समीक्षा हेतु प्रस्तुत किए जाने चाहिए, और अनुमोदन के बाद इस कोश में जोड़े जाने चाहिए।</li><li>यदि किसी शब्द की परिभाषा में संशोधन होता है, तो इस कोश का नवीनतम संस्करण मान्य होगा, और संशोधन-सामग्री दस्तावेज़-संस्करण-टिप्पणियों में भी दर्ज की जानी चाहिए।</li><li>शब्द का उल्लेख करते समय पहली उपस्थिति में पूर्ण नाम और आगे संक्षिप्त नाम उपयोग हो सकता है, किन्तु संदर्भ में अर्थ की स्पष्टता सुनिश्चित करनी होगी।</li></ol><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p>शब्दावली-कोश सम्पूर्ण विश्व-रचना प्रणाली की भाषिक आधारशिला है। एकीकृत शब्दावली-प्रणाली सौ दस्तावेज़ों के बीच अवधारणा-संगति सुनिश्चित करती है, जिससे पाठक बिना समझ-अस्पष्टता के विभिन्न मॉड्यूलों के बीच निर्बाध रूप से परिवर्तन कर सकते हैं। विश्व-रचना प्रणाली के निरंतर समृद्ध और परिपूर्ण होने के साथ यह कोश निरंतर अद्यतन होता रहेगा, और सदैव सभी दस्तावेज़ों का प्राधिकृत शब्दावली-स्रोत बना रहेगा।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (हेंग युआनझोउ: ब्रह्मांड अवलोकन)</li><li>02-锚点本源定义与本质 (लंगर मूल स्रोत: परिभाषा और सार)</li><li>99-文档版本与维护说明 (दस्तावेज़ संस्करण और रखरखाव टिप्पणियाँ)</li></ul>',12)])])}const u=d(i,[["render",l]]);export{b as __pageData,u as default};
